alter table public.saintsai_galeria add column if not exists produto_id uuid, add column if not exists nome text, add column if not exists categoria text, add column if not exists preco numeric(12,2), add column if not exists ano integer, add column if not exists caracteristicas jsonb not null default '{}'::jsonb, add column if not exists posicao integer not null default 0;
alter table public.saintsai_galeria add constraint galeria_produto_preco check(preco is null or preco>=0), add constraint galeria_produto_ano check(ano is null or ano between 1900 and 2100), add constraint galeria_produto_posicao check(posicao>=0), add constraint galeria_produto_self check(produto_id is null or produto_id<>id), add constraint galeria_id_loja unique(id,loja_id), add constraint galeria_produto_empresa foreign key(produto_id,loja_id) references public.saintsai_galeria(id,loja_id) on delete cascade;
create index galeria_produto_fotos on public.saintsai_galeria(loja_id,produto_id,posicao) where ativo;
create table public.saintsai_galeria_contextos(loja_id uuid not null references public.lojas(id) on delete cascade,configuracao_id uuid not null,contato text not null,produto_id uuid not null,etapa text not null check(etapa in ('escolher_produto','oferta_capa','oferta_mais','sem_fotos','recusado')),enviados uuid[] not null default '{}',revisao uuid not null,expira_em timestamptz not null,atualizado_em timestamptz not null default now(),primary key(loja_id,configuracao_id,contato),foreign key(produto_id,loja_id) references public.saintsai_galeria(id,loja_id) on delete cascade);
alter table public.saintsai_galeria_contextos enable row level security;
revoke all on public.saintsai_galeria_contextos from anon,authenticated;
grant all on public.saintsai_galeria_contextos to service_role;
